contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}
    fallback() external payable {}

    function test(address recipient, uint256 amount) public {
        require(address(this).balance >= amount);
        require(amount > 0);

        // fund c through its payable fallback
        (bool okSend, ) = address(c).call{value: amount}("");
        require(okSend);

        uint256 balBefore = address(c).balance;
        uint256 recipBefore = address(recipient).balance;
        require(balBefore > 0);

        (bool ok, ) = address(c).call(abi.encodeWithSelector(C.withdrawAll.selector, recipient));

        assert(ok == false || address(recipient).balance > recipBefore);
    }
}

