    function test(address recipient) public {
        // Call withdrawAll from the test contract itself (zero contract balance is fine).
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSelector(C.withdrawAll.selector, recipient));
        address o = c.owner();
        // General rule: when the caller is the owner, withdrawAll must never revert,
