contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        if (c.owner() != address(this)) {
            try c.withdrawAll{value: amount}(recipient) { reverted = false; } catch { reverted = true; }
        } else {
            try c.withdrawAll{value: amount}(recipient) { reverted = false; } catch { reverted = true; }
        }
        assert(c.owner() == address(this) || reverted);
    }
    receive() external payable {}
}

